interface MuxUICollectionItem {
  id?: string;
  key?: string;
  label?: React.ReactNode;
  value?: string;
  textValue?: string;
  disabled?: boolean;
  [key: string]: unknown;
}

type ColorSwatchPickerOwnProps = {
  items?: MuxUIItems;
  value?: MuxUIColorValue | null;
  defaultValue?: MuxUIColorValue;
  disabled?: boolean;
  readOnly?: boolean;
  onChange?: (value: MuxUIColorValue) => void;
};

type ColorSwatchPickerProps = ColorSwatchPickerOwnProps & {
  className?: string;
} & MuxUIAriaAccessibleName;

type MuxUIAriaAccessibleName = {
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  'aria-label'?: never;
  'aria-labelledby': string;
};
